-- Loads the conflicts and gaps found while reconciling every source document into the
-- To Validate queue (kb_review_queue). Run it once in the Supabase SQL Editor, after supabase.sql.
-- It is safe to run again: an item that is already in the queue is not inserted twice.

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$The 2 year (24 month) warranty is counted from the ETA.$q$, $q$[Warranty start date and length] Hub damaged policy: 2 years from the ETA. Item Received policy export: descriptions say 'under 24 months since the ETA', but the out of warranty instructions say 'starting from the date of delivery' (more than 730 days / 1095 days since delivery). Add-on warranty pack macros: 2 years from the purchase date. Scratches rule: 21 days from the ETA. A marketplace macro (Ali-Express) says '1-year warranty to all jewelry pieces'.$q$, $q$Four different starting points (ETA, delivery date, purchase date) and two different lengths (2 years, 1 year) appear across the sources. This decides whether a claim is in or out of warranty.$q$, $q$Out of warranty rule: 25 to 36 months from the ETA gets 20% off, 36+ months full price.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Warranty start date and length] Hub damaged policy: 2 years from the ETA. Item Received policy export: descriptions say 'under 24 months since the ETA', but the out of warranty instructions say 'starting from the date of delivery' (more than 730 days / 1095 days since delivery). Add-on warranty pack macros: 2 years from the purchase date. Scratches rule: 21 days from the ETA. A marketplace macro (Ali-Express) says '1-year warranty to all jewelry pieces'.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Solid gold is offered in 10K, 14K and 18K (confirm per brand), gold plated and vermeil are 18K gold.$q$, $q$[Solid gold purities offered] Materials FAQ: solid gold 10k, 14k and 18k. Approved vermeil answer from real tickets: solid gold 10K and 14K, gold plated and vermeil 18K. Premium definition in the Damaged policy: 10K, 14K or 18K solid gold. Marketplace macro: solid gold 10k or 14k. Care macro: solid gold purity 9k, 10k and 14k.$q$, $q$The knowledge base itself contains two contradicting statements (one lists 18K solid gold, the other says solid gold is only 10K and 14K), and two macros give other lists. A customer asking about purity gets different answers.$q$, $q$Common facts: 'solid gold in 10k, 14k, and 18k' versus 'solid gold pieces are offered in 10K and 14K'.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Solid gold purities offered] Materials FAQ: solid gold 10k, 14k and 18k. Approved vermeil answer from real tickets: solid gold 10K and 14K, gold plated and vermeil 18K. Premium definition in the Damaged policy: 10K, 14K or 18K solid gold. Marketplace macro: solid gold 10k or 14k. Care macro: solid gold purity 9k, 10k and 14k.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Water resistance can only be confirmed for products showing the Water Resistant badge (theo grace), otherwise give the general care guidance and avoid promising.$q$, $q$[Water resistance, all pieces or only badged ones] Water macro: 'All of our jewelry pieces are water resistant', remove silver, gold plated and vermeil in the shower because soapy water dulls them. Newer theo grace instruction: only products with the blue Water Resistant badge can be called water resistant, others follow the regular policy.$q$, $q$The macro states all pieces are water resistant, the new badge implies it is a per-product feature. The macro may predate the badge.$q$, $q$Common fact: jewelry is water resistant, not waterproof.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Water resistance, all pieces or only badged ones] Water macro: 'All of our jewelry pieces are water resistant', remove silver, gold plated and vermeil in the shower because soapy water dulls them. Newer theo grace instruction: only products with the blue Water Resistant badge can be called water resistant, others follow the regular policy.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$For a damaged item, follow the current policy: reorder, then exchange, then store credit, refund only on request. The 30% coupon and the extra $20 credit in the older macros are not offered unless a team lead confirms.$q$, $q$[Compensation on damaged items (coupon and exchange credit)] Hub damaged policy and the Item Received export: reorder, exchange (customer pays or receives store credit for the price difference), store credit, refund only within 30 days. No coupon is mentioned. Macros (Arrived_Damaged, Damaged_Silver, Gold_Warranty, Silver_Warranty, Reorder_Before_Oct): a 30% coupon valid 6 months and 'pick any other piece with an extra $20 credit on us'.$q$, $q$The macros add gestures (30% coupon, $20 credit) that the current policies never mention. Unclear whether they are still given.$q$, $q$Damaged rules in the knowledge base (marked as legacy macro extras to confirm).$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Compensation on damaged items (coupon and exchange credit)] Hub damaged policy and the Item Received export: reorder, exchange (customer pays or receives store credit for the price difference), store credit, refund only within 30 days. No coupon is mentioned. Macros (Arrived_Damaged, Damaged_Silver, Gold_Warranty, Silver_Warranty, Reorder_Before_Oct): a 30% coupon valid 6 months and 'pick any other piece with an extra $20 credit on us'.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Not Satisfied options are exchange first, then store credit (full amount, valid 1 year), and a refund only for non-personalized or stock items within 30 days. The 10% refund and 30% coupon are not offered unless confirmed.$q$, $q$[Not Satisfied, extra options (10% refund, 30% coupon)] Hub Not Satisfied policy: exchange, then store credit, refund for stock items within 30 days. Macros 10%_Refund_NS and NS_Coupon: a 10% refund of the order or a 30% coupon (valid 6 months) as options where the customer keeps the item.$q$, $q$Two gestures exist only in macros and may be retired.$q$, $q$Not Satisfied rule in the knowledge base.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Not Satisfied, extra options (10% refund, 30% coupon)] Hub Not Satisfied policy: exchange, then store credit, refund for stock items within 30 days. Macros 10%_Refund_NS and NS_Coupon: a 10% refund of the order or a 30% coupon (valid 6 months) as options where the customer keeps the item.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Late compensation is offered from the day after the ETA, the customer chooses from the late compensation options page.$q$, $q$[Late compensation, when it starts and what is offered] Late sub-policy document: offer late compensation when the customer asks a day after the promised date. Late_After_3_days macro: only send when more than 3 business days past the ETA. Amounts in macros: $15 gift card, 20% coupon, 30% coupon, shipping fee refund, 15% refund for USPS/Mailog almost lost cases. The actual options on the late compensation page are not documented anywhere.$q$, $q$Two different starting points (1 day versus 3 business days) and no definitive list of what the customer can choose.$q$, $q$Earlier knowledge base wording: no compensation for a delay under 3 business days.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Late compensation, when it starts and what is offered] Late sub-policy document: offer late compensation when the customer asks a day after the promised date. Late_After_3_days macro: only send when more than 3 business days past the ETA. Amounts in macros: $15 gift card, 20% coupon, 30% coupon, shipping fee refund, 15% refund for USPS/Mailog almost lost cases. The actual options on the late compensation page are not documented anywhere.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$The automatic 20% coupon inside proactive 'might be late' messages is the only compensation given before the ETA has passed.$q$, $q$[Compensation before the ETA is missed] WISMO policy: don't offer compensation before the ETA has passed. Proactive macros (ETA-1 might be late, courier late 1 to 3 business days, will not arrive on time, late supplier) include a 20% coupon before the ETA is missed.$q$, $q$The proactive flow compensates before the ETA, which looks like an exception to the general rule.$q$, $q$WISMO on time rule: no compensation before the ETA.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Compensation before the ETA is missed] WISMO policy: don't offer compensation before the ETA has passed. Proactive macros (ETA-1 might be late, courier late 1 to 3 business days, will not arrive on time, late supplier) include a 20% coupon before the ETA is missed.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$DNR ladder: reorder, then store credit, then (after asking once more about other options) a refund. Lime & Lou never offers a refund in the 'other' case.$q$, $q$[DNR, whether a refund can be offered] Hub WISMO page: the customer may choose a free reorder or a full refund. DNR sub-policy: reorder, store credit, ask again, then refund. Lime & Lou DNR: only reorder or store credit, 'DO NOT OFFER A REFUND'.$q$, $q$The hub page presents reorder and refund as equal choices, the sub-policies make refund the last resort, and Lime & Lou forbids it.$q$, $q$DNR rule in the knowledge base.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[DNR, whether a refund can be offered] Hub WISMO page: the customer may choose a free reorder or a full refund. DNR sub-policy: reorder, store credit, ask again, then refund. Lime & Lou DNR: only reorder or store credit, 'DO NOT OFFER A REFUND'.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Beyond 100 days, offer a free reorder (same item or same price range), and if refused, a 70% refund approved by billing.$q$, $q$[Over 100 days, which date counts and what is offered] Hub: reorders and refunds only within 100 days after the ETA. Sub-policy: 'Over 100 Days Since Delivery ETA' solution exists but its content isn't described. Macros Lost_Over_100: 'more than 100 days after the date of purchase', free reorder first, then a 70% refund.$q$, $q$The 100 days is counted from the ETA in the policies and from the purchase date in the macro, and the dedicated solution's content is only visible in the macro.$q$, $q$Lost order and over 100 days rules in the knowledge base.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Over 100 days, which date counts and what is offered] Hub: reorders and refunds only within 100 days after the ETA. Sub-policy: 'Over 100 Days Since Delivery ETA' solution exists but its content isn't described. Macros Lost_Over_100: 'more than 100 days after the date of purchase', free reorder first, then a 70% refund.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$Without Future Engraving or the add-on pack, a post-purchase addition isn't possible, the courtesy is a 30% coupon for a new item with team lead approval.$q$, $q$[Adding an engraving or charm after purchase] Pre-Sale macro Add_Engraving: a unique 20% code from the coupon bank for a new order. FUTURE_ENGRAVING macro: not possible, 30% coupon via the team lead (non-premium, 6 months). Policy documents: the full repurchase cases (Russian Rings, Heritage Multiple Name, Totem 3D Bar) get a 30% code. Add-on warranty pack macros: gold and diamond items can buy a $40 pack for up to 2 additions within 2 years.$q$, $q$20% versus 30% for the same situation, and it isn't clear whether the add-on pack (Future Engraving) can be purchased after the original order.$q$, $q$Common fact on post-purchase additions and the theo grace Future Engraving facts.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Adding an engraving or charm after purchase] Pre-Sale macro Add_Engraving: a unique 20% code from the coupon bank for a new order. FUTURE_ENGRAVING macro: not possible, 30% coupon via the team lead (non-premium, 6 months). Policy documents: the full repurchase cases (Russian Rings, Heritage Multiple Name, Totem 3D Bar) get a 30% code. Add-on warranty pack macros: gold and diamond items can buy a $40 pack for up to 2 additions within 2 years.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$A misspelling made in our production is reordered free, a customer's own mistake is reordered with a 30% restocking fee (often waived for a typo with approval).$q$, $q$[Manufacturing issue, misspelling versus customer mistake] Item Received export: 'if the customer has in his order a misspelling mistake, we can reorder with no charge', 'if this customer mistake, reorder with a 30% restocking fee'. Macro: any change when the jewelry was made as the customer specified is subject to a 30% restocking fee, typically waived.$q$, $q$The source doesn't say whose misspelling gets the free reorder, and the waiver depends on approval.$q$, $q$Manufacturing issue rule in the knowledge base.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Manufacturing issue, misspelling versus customer mistake] Item Received export: 'if the customer has in his order a misspelling mistake, we can reorder with no charge', 'if this customer mistake, reorder with a 30% restocking fee'. Macro: any change when the jewelry was made as the customer specified is subject to a 30% restocking fee, typically waived.$q$);

insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$If a customer reports a DHL customs fee, apologize, ask for proof of payment and refund it.$q$, $q$[DHL customs fees charged to the customer] New customs delay messages tell the customer there is no customs fee on their end. DHL_Letter macro: customers have been charged customs fees by DHL, the team refunds them on proof of payment within 14 days and sends a DHL letter.$q$, $q$Needs confirmation that this refund still applies and who processes it.$q$, $q$Overseas customs delay rule: 'no customs or paperwork fees on your end'.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[DHL customs fees charged to the customer] New customs delay messages tell the customer there is no customs fee on their end. DHL_Letter macro: customers have been charged customs fees by DHL, the team refunds them on proof of payment within 14 days and sends a DHL letter.$q$);

