insert into kb_review_queue (target, proposed_fact, raw_input, reason, conflicting_with, submitted_by)
select $q$common$q$, $q$For a damaged item, exchange the customer pays or receives store credit for the price difference, the extra $20 credit applies to Not Satisfied exchanges of gold items.$q$, $q$[Premium and non-premium exchange when the item is damaged] Hub damaged policy: exchange, customer pays or receives store credit for the price difference. Macros Arrived_Damaged, OOS_Offer: pick any other piece with an extra $20 credit on us. Hub Not Satisfied: premium exchange covers up to $20 price difference.$q$, $q$The $20 amount appears in both damaged and not satisfied macros but only in the Not Satisfied policy.$q$, $q$Damaged rules in the knowledge base.$q$, 'source reconciliation'
where not exists (select 1 from kb_review_queue where raw_input = $q$[Premium and non-premium exchange when the item is damaged] Hub damaged policy: exchange, customer pays or receives store credit for the price difference. Macros Arrived_Damaged, OOS_Offer: pick any other piece with an extra $20 credit on us. Hub Not Satisfied: premium exchange covers up to $20 price difference.$q$);
